<!--
 * 渠道绑定管理页面
 *
 * <p>管理用户-通知渠道绑定关系，支持查看当前用户的渠道绑定列表、新增绑定、删除绑定。
 *
 * @path apps/message-web/src/views/user-channel-binding/index.vue
 * @author ydsz-team
 * @since 1.0.0
-->
<script lang="ts" setup>
/**
 * 渠道绑定管理（列表页）
 * <p>消费后端契约 UserChannelBindingController（src/api/userChannelBinding.ts，auto-generated by bash/gen-contract.py）：
 * upsert() 新增/更新绑定，listMine() 查询当前用户绑定，
 * listByUser({userId}) 按用户查询绑定，deleteApi({id}) 删除绑定。
 *
 * @author ydsz-team
 * @since 1.0.0
 */
import type { VxeTableGridOptions } from '@ydsz/plugins/vxe-table';

import { Page } from '@ydsz/common-ui';

import { createLogger } from '@YDSZ-core/shared/utils';
import { ElButton, ElInput, ElMessage, ElMessageBox, ElTag } from 'element-plus';
import { h, ref } from 'vue';

import { useYDSZVxeGrid } from '#/adapter/vxe-table';
import { deleteApi, listMine, upsert } from '#/api/userChannelBinding';
import type { MsgUserChannelVO, UserChannelBindingDTO } from '#/api/models';

defineOptions({ name: 'UserChannelBindingManagement' });

const logger = createLogger('user-channel-binding');

/** 当前用户 ID：本子应用无登录态，暂以 'current' 作为当前用户标识 */
const CURRENT_USER_ID = 'current';

/** 快速新增 — 渠道类型 */
const quickChannelType = ref('');

/** 快速新增 — 渠道用户标识 */
const quickChannelUserId = ref('');

/** 验证状态标签类型 */
function getVerifiedType(verified?: number): 'success' | 'warning' {
  return verified === 1 ? 'success' : 'warning';
}

/** 验证状态标签文本 */
function getVerifiedLabel(verified?: number): string {
  return verified === 1 ? '已验证' : '未验证';
}

const gridOptions: VxeTableGridOptions<MsgUserChannelVO> = {
  columns: [
    { type: 'seq', width: 50, title: '序号' },
    { field: 'id', title: 'ID', width: 180 },
    { field: 'channelType', title: '渠道类型', width: 120 },
    { field: 'channelUserId', title: '渠道用户标识', width: 180 },
    {
      field: 'verified',
      title: '验证状态',
      width: 100,
      slots: {
        default: ({ row }) =>
          h(ElTag, { type: getVerifiedType(row.verified) }, () =>
            getVerifiedLabel(row.verified),
          ),
      },
    },
    {
      field: 'isPrimary',
      title: '主通道',
      width: 90,
      slots: {
        default: ({ row }) =>
          h(ElTag, { type: row.isPrimary === 1 ? 'primary' : 'info' }, () =>
            row.isPrimary === 1 ? '是' : '否',
          ),
      },
    },
    { field: 'createdAt', title: '创建时间', width: 170 },
    {
      field: 'action',
      title: '操作',
      width: 120,
      fixed: 'right',
      slots: {
        default: ({ row }) =>
          h('div', { class: 'flex gap-1' }, [
            h(
              ElButton,
              { size: 'small', link: true, type: 'danger', onClick: () => handleDelete(row) },
              () => '删除',
            ),
          ]),
      },
    },
  ],
  height: 'auto',
  proxyConfig: {
    ajax: {
      query: async () => {
        const items = await listMine();
        return { items, total: items.length };
      },
    },
  },
  toolbarConfig: { custom: true, refresh: { code: 'query' }, zoom: true },
};

const [Grid, gridApi] = useYDSZVxeGrid({ gridOptions });

/** 快速新增绑定 */
async function handleQuickCreate(): Promise<void> {
  if (!quickChannelType.value.trim()) {
    ElMessage.warning('请输入渠道类型');
    return;
  }
  if (!quickChannelUserId.value.trim()) {
    ElMessage.warning('请输入渠道用户标识');
    return;
  }
  try {
    const data: UserChannelBindingDTO = {
      userId: CURRENT_USER_ID,
      channelType: quickChannelType.value.trim(),
      channelUserId: quickChannelUserId.value.trim(),
      verified: 0,
      isPrimary: 0,
    };
    await upsert(data);
    ElMessage.success('新增绑定成功');
    quickChannelType.value = '';
    quickChannelUserId.value = '';
    gridApi.query();
  } catch (error) {
    logger.warn('新增绑定失败: {}', error);
    // 错误提示由 errorMessageResponseInterceptor 统一处理
  }
}

/** 删除绑定 */
async function handleDelete(row: MsgUserChannelVO): Promise<void> {
  if (!row.id) return;
  // 步骤1：确认弹窗（用户取消直接返回）
  try {
    await ElMessageBox.confirm(
      `确定删除「${row.channelType} / ${row.channelUserId ?? '-'}」的渠道绑定吗？`,
      '删除确认',
      { type: 'warning' },
    );
  } catch {
    logger.debug('用户取消删除渠道绑定操作');
    return;
  }
  // 步骤2：执行删除 API（失败提示由 errorMessageResponseInterceptor 统一处理）
  try {
    await deleteApi({ id: row.id });
    ElMessage.success('删除成功');
    gridApi.query();
  } catch (error) {
    logger.warn('删除渠道绑定失败: {}', error);
    // 用户提示由 errorMessageResponseInterceptor 统一处理
  }
}
</script>

<template>
  <Page auto-content-height>
    <Grid table-title="渠道绑定管理">
      <template #toolbar-tools>
        <div class="flex items-center gap-3">
          <ElInput
            v-model="quickChannelType"
            placeholder="渠道类型（如 EMAIL/SMS）"
            class="w-44"
            clearable
          />
          <ElInput
            v-model="quickChannelUserId"
            placeholder="渠道用户标识"
            class="w-56"
            clearable
          />
          <ElButton type="primary" @click="handleQuickCreate">新增绑定</ElButton>
        </div>
      </template>
    </Grid>
  </Page>
</template>
